// tables, and extracts/decodes the subset of assets needed for the web port.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { deflateSync } from "node:zlib";

const ROOT = new URL("..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
const KEY = "32768GLB";
const SEED = 0x19;

function decrypt(buf, key = KEY, seed = SEED) { … }

function nameOk(name) { … }

class GLB { … }

const f000 = new GLB(readFileSync(`${ROOT}data/FILE0000.GLB`), "FILE0000");
const f001 = new GLB(readFileSync(`${ROOT}data/FILE0001.GLB`), "FILE0001");

console.log(`FILE0000: ${f000.items.length} items, stride ${f000.stride}`);
console.log(`FILE0001: ${f001.items.length} items, stride ${f001.stride}`);

mkdirSync(`${ROOT}assets`, { recursive: true });
mkdirSync(`${ROOT}assets/raw`, { recursive: true });
writeFileSync(
  `${ROOT}assets/items.json`,
  JSON.stringify({ FILE0000: f000.items, FILE0001: f001.items }, null, 0)
);

// ---- minimal PNG writer for verification previews
function crc32(buf) { … }
function pngChunk(type, data) { … }
function writePNG(path, w, h, rgb /* Uint8Array w*h*3 */) { … }

// ---- GFX item decoding
// GFX_PIC header: { INT type, INT opt1, INT opt2, INT width, INT height } = 20 bytes
// type 1 (GPIC): followed by width*height palette indices (opaque).
// type 0 (GSPRITE): followed by height * 16-byte descriptors {INT x, INT y, INT offset, INT length}
//   then a pixel pool.
function decodeGfx(buf) { … }

// render a decoded gfx to RGB using a palette (for verification only)
function renderGfx(pic, palette) { … }

const pal = f001.bytes(f001.get(0));
console.log("item0 size:", pal.length);
const prgb = new Uint8Array(16 * 16 * 4 * 3);
for (let i = 0; i < 256; i++) { … }
writePNG(`${ROOT}assets/preview_palette.png`, 64, 64, prgb);

// list interesting items from FILE0001
for (const it of f001.items) { … }

// map decode: MAZELEVEL { DWORD sizerec, DWORD spriteoff, INT numsprites, MAZEDATA map[1350] }
// MAZEDATA { SHORT flats, SHORT fgame }
const mapItem = f001.get("MAP1G1_MAP") || f001.items[254];
const mapb = f001.bytes(mapItem);
console.log(`\n${mapItem.name} size=${mapb.length}`);
const numspr = mapb.readInt32LE(8);
console.log("numsprites:", numspr);
const csprites = [];
for (let i = 0; i < numspr; i++) { … }
console.log("csprites:", JSON.stringify(csprites.slice(0, 12)));

// flats table (FLATSG1_ITM): FLATS { INT linkflat, SHORT bonus, SHORT bounty }
const flatItem = f001.get("FLATSG1_ITM") || f001.items[253];
const flatb = f001.bytes(flatItem);
const numflats = Math.floor(flatb.length / 8);
console.log(`flats item ${flatItem.name} size=${flatb.length} entries=${numflats}`);
const flats = [];
for (let i = 0; i < numflats; i++) flats.push({ linkflat: flatb.readInt32LE(i * 8), bonus: flatb.readInt16LE(i * 8 + 4), bounty: flatb.readInt16LE(i * 8 + 6) });
const usedFlats = new Set();
for (let i = 0; i < 1350; i++) { … }
console.log("used flats:", [...usedFlats].join(","));
for (const f of usedFlats) { … }

// player ship frame 0 + enemy sprite previews
const ship = decodeGfx(f001.bytes(f001.get(282)));
console.log(`\nLPLAYER_PIC item282: type=${ship.type} ${ship.w}x${ship.h}`);
